import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Autorité et authentification de collaboration","description":"","frontmatter":{"title":"Autorité et authentification de collaboration","docId":"developer.collaboration","translationKey":"developer.collaboration","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","translationRevision":"12ac7b010630ad128b026385ded2f897811b484b9ab46c73b84462048134d842","order":190},"headers":[],"relativePath":"fr/developer/collaboration.md","filePath":"fr/developer/collaboration.md","lastUpdated":1794611623000}'),o={name:"fr/developer/collaboration.md"};function n(r,e,l,c,p,d){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="collaboration-authority-and-authentication" tabindex="-1">Autorité et authentification de collaboration <a class="header-anchor" href="#collaboration-authority-and-authentication" aria-label="Permalink to &quot;Autorité et authentification de collaboration {#collaboration-authority-and-authentication}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Permettre à un appareil approuvé d’examiner ou d’effectuer une opération précisément délimitée sur un hôte existant. Utilisez un profil propriétaire de test, une compilation avec prise en charge distante et un transport configuré. La connexion au compte, l’appartenance à une équipe Cloud, la propriété locale et une session déléguée directe sont des autorités distinctes.</p><h2 id="establish-the-trust-chain" tabindex="-1">Établir la chaîne de confiance <a class="header-anchor" href="#establish-the-trust-chain" aria-label="Permalink to &quot;Établir la chaîne de confiance {#establish-the-trust-chain}&quot;">​</a></h2><p>L’administration <code>collaboration.*</code> du propriétaire local possède configuration, invitations, demandes en attente, principaux, autorisations, sessions et audit. Découvrez les schémas avant de configurer un écouteur ou de créer des identifiants :</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.configure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.invites.create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>Une invitation lance l’appairage ; elle n’accorde pas à elle seule l’autorité métier. L’approbation du propriétaire crée la session/les autorisations appropriées. HTTPS direct exige des certificats validés ou une confiance native explicitement épinglée. Les frontières des jetons porteurs natifs et des cookies navigateur diffèrent. Le <code>collaboration.hello</code> initial lie protocole, instance d’hôte, principal, session, révision d’autorisation, capacités et limites négociées.</p><h2 id="authorize-each-operation" tabindex="-1">Autoriser chaque opération <a class="header-anchor" href="#authorize-each-operation" aria-label="Permalink to &quot;Autoriser chaque opération {#authorize-each-operation}&quot;">​</a></h2><p>Une méthode distante prise en charge doit passer ses vérifications de liste autorisée, capacité, restriction de ressource et session actuelle. La désactivation/suppression de workflow utilise des métadonnées durables de comparaison et modification atomiques. Les ajustements de points sont additifs et possèdent leurs propres limites d’autorisation. Les lectures d’automatisation distantes sont des résumés fermés ; les brouillons désactivés appartenant à leur auteur n’acquièrent pas l’autorité exécutable du propriétaire simplement en étant enregistrés.</p><p>L’examen/adoption par le propriétaire et l’approbation vérifiée lient les définitions, dépendances et provenances actuelles. Un manifeste d’aperçu rapporte des données d’inspection, pas un jeton d’exécution. Revalidez les autorisations et liaisons de ressources aux frontières d’exécution plutôt que de traiter l’identité de transport comme une permission permanente.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>La collaboration native directe implémente des lectures délimitées, certaines mutations durables et une récupération bornée. Les équipes/relais Cloud ont en plus leurs propres adaptateurs ; le parcours de lecture du relais Cloud documenté ne doit pas être présenté comme une modération complète ou l’exécution de brouillons. Les effets délégués, écritures métier et validations multi-PC restants demeurent expérimentaux. Consultez les <a href="./remote-client.html">clients distants</a> et <a href="./cloud.html">Cloud</a> pour le parcours sélectionné.</p><h2 id="recover-and-verify" tabindex="-1">Récupérer et vérifier <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;Récupérer et vérifier {#recover-and-verify}&quot;">​</a></h2><p>À la révocation ou au changement d’identité, arrêtez les abonnements et supprimez les projections privées. Utilisez <code>collaboration.subscribe</code>, <code>snapshot</code> et <code>resume</code> selon les domaines négociés et la validité du curseur. Résolvez l’identifiant de commande original après un accusé incertain. Ne réessayez pas une suppression avec un nouvel identifiant et ne restaurez pas une autorité depuis un ancien reçu. La <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-collaboration/src" target="_blank" rel="noreferrer">source d’autorisation</a> et la politique du registre définissent la frontière ; réussir TLS seul n’est pas un test d’autorisation.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Séquence Teams : enregistrez l’appareil, émettez/rejoignez une invitation ou demande, approuvez puis faites confirmer par l’hôte la révision actuelle de permission native. <code>pendingHost</code> indique cette dernière étape. Une nouvelle révision invalide la confirmation ; rechargez si expectedRevision est périmée. L’acceptation native exige instantané récent, hôte/appareil actifs, permission active et confirmedRevision égale à revision. L’UI expose panneaux hôte/jonction et approbations disponibles ; la confirmation native est un contrat API, pas un bouton garanti partout.</p><p>Conversion héritée fermée : observer lit live/workflows/points/compétitions/automatisation/résultats ; moderator ajoute ajustement de points, toggles workflow/automatisation et gestion des compétitions ; automationEditor ajoute édition aux lectures. Aucun preset n’implique scripts arbitraires, effets externes ou délégation réutilisable. <code>nativeGrant</code> explicite exige <code>custom</code> ; limitez ressources, effets et delta. Client natif : <code>desktop</code> ou <code>agent</code> seulement. Une politique non supportée échoue sans élargir les droits. Diagnostiquez pairing, confirmation, révision et transport séparément.</p>`,17)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
